import json
n=27
g=[[3]*n for _ in range(n)]
# legend
legend=[[1,1,1],[4,4,2],[1,4,1],[8,0,0]]
for r,row in enumerate(legend):
    for c,v in enumerate(row):
        if v: g[1+2*r][1+2*c]=v
# scaled pattern: 4x4 cells, one-cell gaps, top-left (5,8)
for r,row in enumerate(legend):
    for c,v in enumerate(row):
        if v:
            for rr in range(5+5*r,5+5*r+4):
                for cc in range(8+5*c,8+5*c+4): g[rr][cc]=v
print(json.dumps({'action':'submit','grid':g}))
